{"path":"/root/solve.py","content":"#!/usr/bin/env python3
"""Generate infusion batch analysis artifacts from task input files."""

import csv
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent

ASSUMPTIONS = {
    "deliveries_per_year_7_day": 52,
    "deliveries_per_year_14_day": 26,
    "days_per_delivery_7_day": 7,
    "days_per_delivery_14_day": 14,
    "switch_threshold_usd": 15000,
    "patient_override_rule": "highest approved revision per therapy_code",
}


def normalize_label(value):
    return value.strip().casefold()


def money(value):
    return round(float(value) + 0.0, 2)


def load_in_scope_therapies(path):
    with path.open() as f:
        catalog = json.load(f)

    therapies = []
    label_to_therapy = {}
    for service_line in catalog.get("service_lines", []):
        for therapy in service_line.get("therapies", []):
            if therapy.get("include_in_review") is True:
                therapies.append(therapy)
                labels = [therapy["therapy_name"], *therapy.get("aliases", [])]
                for label in labels:
                    label_to_therapy[normalize_label(label)] = therapy
    return therapies, label_to_therapy


def load_bag_supply_costs(path):
    with path.open(newline="") as f:
        return {
            int(row["bag_size_ml"]): float(row["bag_supply_cost_usd"])
            for row in csv.DictReader(f)
        }


def load_delivery_payments(path, label_to_therapy):
    payments = {}
    with path.open(newline="") as f:
        for row in csv.DictReader(f):
            therapy = label_to_therapy.get(normalize_label(row["therapy_label"]))
            if therapy is None:
                continue
            payments[therapy["therapy_code"]] = float(
                row["payment_per_delivery_per_patient_usd"]
            )
    return payments


def load_active_patient_overrides(path, in_scope_codes):
    selected = {}
    with path.open(newline="") as f:
        for row in csv.DictReader(f):
            therapy_code = row["therapy_code"]
            if row["status"] != "approved" or therapy_code not in in_scope_codes:
                continue
            revision = int(row["revision"])
            if therapy_code not in selected or revision > selected[therapy_code]["revision"]:
                selected[therapy_code] = {
                    "revision": revision,
                    "active_patients": int(row["active_patients"]),
                }
    return {
        therapy_code: data["active_patients"]
        for therapy_code, data in selected.items()
    }


def build_analysis():
    therapies, label_to_therapy = load_in_scope_therapies(ROOT / "therapy_catalog.json")
    in_scope_codes = {therapy["therapy_code"] for therapy in therapies}
    bag_supply_costs = load_bag_supply_costs(ROOT / "bag_supply_cost.csv")
    delivery_payments = load_delivery_payments(
        ROOT / "delivery_payment.csv", label_to_therapy
    )
    active_patients_by_code = load_active_patient_overrides(
        ROOT / "patient_overrides.csv", in_scope_codes
    )

    therapy_rows = []
    for therapy in therapies:
        therapy_code = therapy["therapy_code"]
        active_patients = active_patients_by_code[therapy_code]
        bag_supply_cost = bag_supply_costs[int(therapy["bag_size_ml"])]
        payment = delivery_payments[therapy_code]
        drug_cost_per_1000_mg = float(therapy["drug_cost_per_1000_mg_usd"])
        dose_mg_per_day = float(therapy["dose_mg_per_day"])

        annual_drug_cost_7 = money(
            drug_cost_per_1000_mg * active_patients * dose_mg_per_day * 7 * 52 / 1000
        )
        annual_drug_cost_14 = money(
            drug_cost_per_1000_mg * active_patients * dose_mg_per_day * 14 * 26 / 1000
        )
        annual_supply_cost_7 = money(bag_supply_cost * active_patients * 52)
        annual_supply_cost_14 = money(bag_supply_cost * active_patients * 26)
        annual_revenue_7 = money(payment * active_patients * 52)
        annual_revenue_14 = money(payment * active_patients * 26)
        annual_margin_7 = money(
            annual_revenue_7 - annual_drug_cost_7 - annual_supply_cost_7
        )
        annual_margin_14 = money(
            annual_revenue_14 - annual_drug_cost_14 - annual_supply_cost_14
        )
        annual_margin_difference = money(annual_margin_14 - annual_margin_7)

        therapy_rows.append(
            {
                "therapy_code": therapy_code,
                "therapy_name": therapy["therapy_name"],
                "active_patients": active_patients,
                "bag_size_ml": int(therapy["bag_size_ml"]),
                "bag_supply_cost_usd": money(bag_supply_cost),
                "payment_per_delivery_per_patient_usd": money(payment),
                "annual_drug_cost_7_day_usd": annual_drug_cost_7,
                "annual_drug_cost_14_day_usd": annual_drug_cost_14,
                "annual_supply_cost_7_day_usd": annual_supply_cost_7,
                "annual_supply_cost_14_day_usd": annual_supply_cost_14,
                "annual_revenue_7_day_usd": annual_revenue_7,
                "annual_revenue_14_day_usd": annual_revenue_14,
                "annual_margin_7_day_usd": annual_margin_7,
                "annual_margin_14_day_usd": annual_margin_14,
                "annual_margin_difference_14_minus_7_usd": annual_margin_difference,
            }
        )

    therapy_rows.sort(key=lambda row: row["therapy_code"])

    total_margin_7 = money(sum(row["annual_margin_7_day_usd"] for row in therapy_rows))
    total_margin_14 = money(sum(row["annual_margin_14_day_usd"] for row in therapy_rows))
    total_difference = money(
        sum(row["annual_margin_difference_14_minus_7_usd"] for row in therapy_rows)
    )
    absolute_difference = money(abs(total_difference))

    decision = (
        "move_to_14_day"
        if absolute_difference < ASSUMPTIONS["switch_threshold_usd"]
        else "keep_7_day"
    )
    comparison = "below" if decision == "move_to_14_day" else "above or equal to"
    justification = (
        f"Absolute margin difference of ${absolute_difference:,.2f} is {comparison} "
        f"the $15,000 threshold, so recommend {decision}."
    )

    return {
        "assumptions": ASSUMPTIONS,
        "therapies": therapy_rows,
        "totals": {
            "total_annual_margin_7_day_usd": total_margin_7,
            "total_annual_margin_14_day_usd": total_margin_14,
            "total_annual_margin_difference_14_minus_7_usd": total_difference,
            "absolute_total_margin_difference_usd": absolute_difference,
        },
        "recommendation": {
            "decision": decision,
            "justification": justification,
        },
    }


def write_summary(path, analysis):
    totals = analysis["totals"]
    decision = analysis["recommendation"]["decision"]
    lines = [
        "# Infusion Batch Analysis Summary",
        f"Total 7-day margin: ${totals['total_annual_margin_7_day_usd']:,.2f}",
        f"Total 14-day margin: ${totals['total_annual_margin_14_day_usd']:,.2f}",
        f"Absolute difference: ${totals['absolute_total_margin_difference_usd']:,.2f}",
        f"Decision: {decision}",
        analysis["recommendation"]["justification"],
    ]
    path.write_text("\n".join(lines) + "\n")


def main():
    analysis = build_analysis()
    with (ROOT / "infusion_batch_analysis.json").open("w") as f:
        json.dump(analysis, f, indent=2)
        f.write("\n")
    write_summary(ROOT / "infusion_batch_summary.md", analysis)


if __name__ == "__main__":
    main()
